SKquests_GuideES = { Alliance = {}, Horde = {} }
SKquests_GuideES.Alliance[1] = {title = [[Human - Northshire Abbey]], text = [[
01) justo afuera de Northshire Abbey's entrance, desde Deputy Willem, entrega "Brotherhood of Thieves" 48.44.  acepta "Milly Osworth" y "Bounty on Garrick Padfoot".
02) justo afuera de Northshire Abbey repara y reabastécete en 47.42.
03) entra en Echo Ridge Mine al norte (entrada en 48.32) y haz "Skirmish at Echo Ridge": mata Kobold Laborers.
04) ve a al NE de Northshire Abbey (junto a establos/carreta) y entrega "Milly Osworth" 51.39, acepta "Milly's Harvest".
05) cruzal río al este hacia Northshire Vineyards alrededor de 54.49 y haz "Milly's Harvest": saquea Milly's Harvest (cajas) del suelo alrededor de farm.  ten presente el siguiente paso:
06) justo al este del Northshire Vineyards do "Bounty on Garrick Padfoot": mata y saquea a Garrick Padfoot /target (frente a shack, 57.48).
07) asegúrate de ser nivel 5.  Muere a propósito y revive en el Sanador de Espíritus, luego ve a al NE de Northshire Abbey (junto a establos/carreta) y entrega "Milly's Harvest" 51.39 (#4 en map), acepta "Grape Manifest".
08) frente a Northshire Abbey's entrance, desde Deputy Willem, entrega "Bounty on Garrick Padfoot" 48.44 (#1 en map).
09) justo dentro de Northshire Abbey, entrega "Skirmish at Echo Ridge" 49.42.  acepta "Report to Goldshire".
10) gira a la derecha dentro de de Northshire Abbey, luego sube por spiral staircase entrance 50.41 hasta lo alto de Abbey y entrega "Grape Manifest" 49.42.
11) sal afuera de Northshire Abbey y repara y reabastécete en 47.42 (#2 en map).
12) sal de Northshire Valley yendo hacia SW salida 47.48.
13) frente al fuente del león, acepta "Rest and Relaxation" 46.48.
 ]], }
SKquests_GuideES.Alliance[2] = {title = [[11 Goldshire]], text = [[
01) sigue el camino principal sur a Goldshire y asegúrate de estar al menos a 325 XP away desde nivel 6 (2,475 XP into lvl 5) para aprender nuevas habilidades (puedes matar enemigos oeste de main path), luego ve a Goldshire y frente a refinery, entrega "Report to Goldshire" 42.66, acepta "The Fargodeep Mine".
02) entra en Goldshire's Inn (entrada en 43.66).  gira cerrado a la izquierda y acepta "Kobold Candles" 43.66.
03) Next a en Innkeeper Farley 44.66, entrega "Rest and Relaxation".  Also make Goldshire tu new home para tu Hearthstone desdel Innkeeper.  Make sure están resupplied.
04) Get tu nivel 6 spells/abilities en Goldshire.
05) If have an extra silver a spare:  Upstairs en Inn y en middle room desdel Physician 43.66, learn Apprentice First Aid.
06) On el sur side de Goldshire by el carreta, acepta "Gold Dust Exchange" 42.67.
07) Go SW a The Stonefield Farm y junto a housa, acepta "Lost Necklace" 34.84 y "Princess Must Die!" 35.84.  ALSO:  While de camino, start mata y saquea aing boars a recoge  Chunk de Boar Meats (para a future misión), y hazn't sell them a a vendedor!
08) ve al este a The Maclure Vineyards y frente a barn entrega "Lost Necklace" 43.86, acepta "Pie for Billy".
09) ve al sur en The Maclure Vineyards y en small housa, acepta "Young Lovers" 43.90.
10) Stop en vendedor /target 42.89 a get resupplied.  NOTE:  remember not a sell tu Chunk de Boar Meats!
11) ve al oeste a The Stonefield Farm (watch out para lvl 9 bears) y junto a river entrega "Young Lovers" 30.86, acepta "Speak with Gramma".  ALSO:  While de camino, farmea en Boars a recoge 4 Chunk de Boar Meats (para a future misión), y hazn't sell them a a vendedor!
12) All alrededor de southern Elwynn Forest alrededor de 33.85 do "Pie for Billy": mata y saquea a Boars.  NOTE:  You may already have el 4 Chunk de Boar Meats by farmeaing previously!
13) At el small housa en The Stonefield Farm, junto a well (35.84, #7 en map), entrega "Pie for Billy", acepta "Back to Billy".
14) In el small housa este en The Stonefield Farm, entrega "Speak with Gramma" (35.84, #7 en map), acepta "Note to William".
15) ve al este a The Maclure Vineyards y frente a barn entrega "Back to Billy" (43.86, #8 en map), acepta "Goldtooth".
 ]], }
SKquests_GuideES.Alliance[3] = {title = [[Human - Elwynn Forest]], text = [[
01) Go NW a Fargodeep Mine y take el upper mine entrance 39.82.  Keep hugging el left side de la mina until get a Goldtooth /target 42.78 y mata y saquea a him para "Goldtooth".  Luego make sure "Gold Dust Exchange" along con "Kobold Candles" está finished by mata y saquea aing el Kobolds dentro de or afuera de la mina.
02) Exit la mina salida 39.82, luego go entrega "Goldtooth" 35.84.
03) Vendor, 2a) Stop en Fruit Seller /target 34.83 a sell tu junk.
04) farmea tu way back a Goldshire, asegúrate de estar al menos a 2,680 XP into nivel 7 before getting there.  Luego by el carreta, entrega "Gold Dust Exchange" 42.67, acepta "A Fishy Peril".
05) frente a la refinería, entrega "The Fargodeep Mine" 42.66, acepta "The Jasperlode Mine".  And entrega "A Fishy Peril", acepta "Further Concerns".
06) Repara y reabastécete en (en la refinería) 42.66.
07) In el Inn, cerca del entrance, entrega "Kobold Candles" 43.66, acepta "Shipment to Stormwind".  Also entrega "Note to William", acepta "Collecting Kelp".
08) First Aid? 6a) It's wise now a make sure get Apprentice First Aid if haven't yet:  Go upstairs en Inn y en middle room desdel Physician 43.66, learn Apprentice First Aid.
09) Get tu nivel 8 spells/abilities en Goldshire.
10) ve al este a bit a Crystal Lake alrededor de 56.69 y haz "Collecting Kelp": mata y saquea al murlocs alrededor del lago.  TIP: Avoid going hacia islands en el lago, stay alrededor del perimeter del lago para easy spaced out targets.
11) Go NE y entra en Jasperlode Mine (entrada en 62.53) y haz "The Jasperlode Mine": work tu way into la mina until get it scouted.
12) Go SE al puente where el main path y el río meet y luego entrega "Further Concerns" 74.72, acepta "Find the Lost Guards" y "Protect the Frontier".
13) Go NE a bit a Eastvale Logging Camp en small housa y acepta "Red Linen Goods" 80.69.
14) NE a bit more, junto a carreta, acepta "A Bundle of Trouble" 81.66.
15) Just este, can ve al Bowyer 83.66 a get repaired/resupplied.
 ]], }
SKquests_GuideES.Alliance[4] = {title = [[Alliance - Westfall]], text = [[
01) Go justo al norte de Eastvale Logging Camp alrededor de 80.61 y start working en "Protect the Frontier" y "A Bundle of Trouble": mata Prowlers (wolves) y Young Forest Bears.  Also saqueal Bundle de Wood alrededor del trees.  Work tu way hacia next step:
02) farmea NW hacia shore y click en A half-eaten body 73.60 a entrega "Find the Lost Guards", acepta "Discover Rolf's Fate".
03) Go NE junto a murloc camp (watch out paral multiple murlocs) y click en Rolf's corpse 80.55 a entrega "Discover Rolf's Fate", acepta "Report to Thomas".
04) Make sure "A Bundle of Trouble" está finished by saqueaing el Bundle de Wood alrededor del trees norte de Eastvale Logging Camp.  Also finish "Protect the Frontier" by mataing Prowlers (wolves, #1 en map) y Young Forest Bears.
05) ve al middle de Eastvale Logging Camp, junto a carreta y entrega "A Bundle of Trouble" 81.66.
06) You can ve al este a bit hacia Bowyer 83.66 a get repaired/resupplied.
07) ve a where el main path y el río meets 74.72 y entrega "Protect the Frontier" y "Report to Thomas", acepta "Deliver Thomas' Report".  Also acepta "Report to Gryan Stoutmantle".
08) Go SW a Brackwell Pumpkin Patch alrededor de 70.79 y haz "Red Linen Goods": mata y saquea al Defias enemigos paral bandanas alrededor de la granja.  NOTE:  Any de Defias enemigos has a very low chance a drop an item called Westfall Deed, which starts "Furlbrow's Deed" (acepta it if están able a find it).  ten presente el siguiente paso:
09) At Brackwell Pumpkin Patch, attempt "Princess Must Die!": try a mata y saquea a Princess /target.  This lvl 9 boar patrols alrededor de la granja y has two lvl 7 bodyguards.  TIPS: If can get help cerca de by, do so.  You can usa fences a jump alrededor de them as el boars will keep running alrededor de them.  If did not succeed, will be able a solo this later.  Don't worry about dying becausa that está what we will want a do next anyways.
 ]], }
SKquests_GuideES.Alliance[5] = {title = [[Human - Elwynn Forest]], text = [[
01) At el small housa en Eastvale Logging Camp, entrega "Red Linen Goods" 79.69.
02) usa la piedra de hogar hacia Goldshire.
03) In el Inn, cerca del entrance, entrega "Collecting Kelp" 43.66.  Wait a few seconds, luego acepta "The Escape".
04) justo afuera del Inn, frente a refinery 42.66, entrega "The Jasperlode Mine" y "Deliver Thomas' Report", acepta "Cloth and Leather Armor".  Also acepta "Westbrook Garrison Needs Help!".
05) entra en refinery next a y acepta "Elmore's Task" 42.66.  Repara y reabastécete en.
06) ve al sur a The Maclure Vineyards y en small housa, entrega "The Escape" 43.90.
07) ve al oeste a The Stonefield Farm y frente a small housa, entrega (if did it) "Princess Must Die!" 35.84.
08) Go NW a Westbrook Garrison y frente a garrison's entrance, desdel Wanted Poster 25.75, acepta "Wanted:  "Hogger".
09) Next to you, turn in "Westbrook Garrison Needs Help!" 24.74, accept "Riverpaw Gnoll Bounty".
 ]], }
SKquests_GuideES.Alliance[6] = {title = [[11 Westfall + Stormwind]], text = [[
01) sigue el camino principal oeste a entra en Westfall, y just off a tu right junto a carreta, entrega (if have it) "Furlbrow's Deed" (60.19 en Westfall).  Next a, acepta "Westfall Stew".
02) sigue el camino principal sur y off a tu right entra en housa en Saldean's Farm y entrega "Westfall Stew" 56.30, SKIP el next part.
03) ve al sur a Sentinel Hill en la torre y entrega "Report to Gryan Stoutmantle" 56.47, SKIP "The People's Militia".
04) Back dentro de la torre, acepta "A Swift Message" 57.47.
05) justo al sur de la torre, en Gryphon Master 57.53, entrega "A Swift Message", acepta "Continue to Stormwind".  Luego take a flight a Stormwind, Elwynn.
06) In Stormwind, ve a Old Town y en Limited Immunity, entrega "Continue to Stormwind" 77.61, acepta "Dungar Longdrink".
07) Near el entrance en Stormwind, entra en Pestle's Apothecary y entrega "Shipment to Stormwind" 63.74.
08) Slightly norte, can go en Weller's Arsenal y desdel Weapon Master 64.69, can learn new weapon possibilities if can afford a.
09) ve al este hacia Gryphon Master 71.73 en Stormwind y entrega "Dungar Longdrink", acepta "Return to Lewis".  Luego fly a Sentinel Hill, Westfall.
10) In Westfall, ve al norte a bit dentro de la torre y entrega "Return to Lewis" (57.47, #3 en map).
 ]], }
SKquests_GuideES.Alliance[7] = {title = [[Human - Elwynn Forest]], text = [[
01) 12 Elwynn Forest
02) ve a Forest's Edge alrededor de 27.86 y haz "Riverpaw Gnoll Bounty": mata y saquea a Riverpaw gnolls.  NOTES:  While doing this misión any de gnolls has a very small chance de dropping an item called Gold Pickup Schedule, which starts "The Collector", acepta it if están able a find it.  A rare mob named Gruff Swiftbite /target has a 100% drop rate para that item, so keep an eye out para him.  Also, while doing this misión can recolecta a group y luego work tu way a do el next misión:
03) If have a group can try a do "Wanted:  "Hogger": kill/loot Hogger /target (lvl 11 Elite gnoll).  If you don't have a group, you can attempt to solo him if you dare, if not it can be skipped.
04) Go north to Westbrook Garrison and in front of the entrance, turn in "Riverpaw Gnoll Bounty" 24.74.
05) Die on purpose (res at spirit) to get back to Goldshire and in front of the refinery 42.66, turn in (if you have it) "The Collector" and (if you did it) "Wanted:  "Hogger".  If it's available, acepta "Manhunt".  Repara y reabastécete en en la refinería.
06) ve al este en main path y en el puente/river acepta "Bounty on Murlocs" 74.72.
07) Do (if have it) "Manhunt": go SW a Brackwell Pumpkin Patch y en small housa mata y saquea a Morgan el recogeor 71.81.  ALSO:  If haven't yet, en Brackwell Pumpkin Patch  can try a do "Princess Must Die!": mata y saquea a Princess /target.  This lvl 9 boar patrols alrededor de la granja y has two lvl 7 bodyguards.  Try a team up con someone en area if can or can try a solo it.  If can't do it, luego skip it.
08) Do "Bounty on Murlocs": mata y saquea a Murlocs along el coast del río sur running a través de Elwynn Forest alrededor de 70.84.
09) vuelve al puente where el main path y el río meet y entrega "Bounty on Murlocs" (74.72, #5 en map).
10) Go NE a Eastvale Logging Camp y en small housa entrega "Cloth and Leather Armor" 80.69.
11) sigue el camino principal este into Redridge Mountains (94.72 en Elwynn Forest).
12) sigue el camino principal este y en first intersection, acepta "Encroaching Gnolls" (15.71 en Redridge).
13) Go NE y en tu left before el puente entrega "Encroaching Gnolls" 31.60, acepta "Assessing the Threat".
14) Next a, get el Flight Path desdel Gryphon Master 31.59.
15) If need a entrega either "Manhunt" or "Princess Must Die!" luego usa la piedra de hogar hacia Goldshire.  If cannot hearth luego fly a Stormwind, drop en water a die en purpose, y res en spirit a get back a Goldshire.  If DONT need a entrega either de those misiones luego just fly a Stormwind, Elwynn y skip hacia next section below.
16) Upgrade First Aid en Inn (if need a), luego salidal Inn, y frente a refinery entrega "Manhunt" (42.66, #4 en map).  Repara y reabastécete en.
17) If did "Princess Must Die!", go SW a The Stonefield Farm y frente a small housa 35.84, turn it en.  Afterwards ve al este a bit y die en purpose hacia kobolds alrededor de 37.83, luego res en spirit.
 ]], }
SKquests_GuideES.Alliance[8] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) 12 Ironforge + Dun Morogh
02) If still have any de following misiones en tu questbook, they can be Abandoned:  "Wanted: "Hogger" and "Princess Must Die!".
03) Go north to enter Stormwind, then go to the Dwarven District and turn in "Elmore's Task" 60.34.  Accept "Stormpike's Delivery".
04) Go NE in the Dwarven District to enter the Deeprun Tram 69.31.  Then wait for the tram ride to show up and it will take you to Ironforge's side of the Deeprun Tram.
05) Once at the other side of the Deeprun Tram, accept "Deeprun Rat Roundup" (this is accepted between the two Tram tracks).
06) Just around the immediate area do "Deeprun Rat Roundup": use the Rat Catcher's Flute quest item on the Deeprun Rats.
07) Go back between the two tracks at the Deeprun Tram, and turn in "Deeprun Rat Roundup".  NOTE:  "Me Brother, Nipsy" will be skipped for now.
08) Exit the Deeprun Tram by heading north through the tunnel..
09) In the middle of Ironforge at The Great Forge, get the Flight Path there from the Gryphon Master 56.48.
10) First Aid? 08a) You can upgrade First Aid up in Ironforge Physician, entrance at 55.57.
11) Go SW to leave Ironforge (exit at 15.86).
12) In Dun Morogh, follow the main path east to Gol'Bolar Quarry and accept "The Public Servant" 69.56.
13) Next to you, behind the tent, accept "Those Blasted Troggs!" 69.56.
14) Drop down in the Quarry and enter the mine (entrance at 71.56) and do "The Public Servant" along with "Those Blasted Troggs!": kill Rockjaw Skullthumpers and Rockjaw Bonesnappers (only in mine).  Focus inside the mine more, as both of the these mobs are found in there.
15) Go back up and turn in "The Public Servant" (69.56, #10 on map).
16) Next to you, behind the tent, turn in "Those Blasted Troggs!" 69.56.
17) sigue el camino principal este a entra en Loch Modan (entrada en 86.51)..
 ]], }
SKquests_GuideES.Alliance[9] = {title = [[Alliance - Loch Modan]], text = [[
01) 13 Loch Modan
02) Once entra en Loch Modan  will arrive en Valley de Kings, y frente a watchtower, acepta "In Defense of the King's Lands" (22.73 en Loch Modan).
03) Go up en watchtower frente a y acepta "The Trogg Threat" 23.74.
04) sigue el camino principal NE, luego gira a la derecha a ve a Stonesplinter Valley alrededor de 32.73 y haz "In Defense of the King's Lands" along con "The Trogg Threat": mata 10 Stonesplinter Troggs y 10 Stonesplinter Scouts, y saquea them paral Stone Tooth.
05) Go back oeste a Valley de Kings y entrega "In Defense of the King's Lands" (22.73, #1 en map).
06) Go up en watchtower y entrega "The Trogg Threat" 23.74.
07) ve al norte a Thelsamar alrededor de 34.48 y find Mountaineer Kadrell /target (he patrols alrededor de town) y acepta "Rat Catching" y "Mountaineer Stormpike's Task".
08) entra en Inn (el building con el big barriles alrededor de it) y el first NPC see (Innkeeper Hearthstove, 35.48), talk a him a make this Inn tu new home.
09) At el bar, desde Vidra Hearthstove, acepta "Thelsamar Blood Sausages" 35.49.  Make sure están resupplied.  If need 6 slot bags, can purchase them desdel General Supplies vendedor en Inn (if can afford them).
 ]], }
SKquests_GuideES.Alliance[10] = {title = [[Alliance - Loch Modan]], text = [[
01) While working tu way norte hacia next steps, also start working en "Rat Catching" by mata y saquea aing Tunnel Rat enemigos (kobolds) along el oeste side de main path (#3 en map).  Also start working en "Thelsamar Blood Sausages" by mataing boars, bears y spiders (en open fields de Loch Modan, #1 en map):
02) farmea norte a Algaz Station, go up en watchtower y entrega "Stormpike's Delivery".  And entrega "Mountaineer Stormpike's Task" 25.18, acepta "Stormpike's Order".  acepta "Filthy Paws".  NOTE:  You can get repaired/resupplied en bottom de watchtower but do not sell tu "Thelsamar Blood Sausages" misión items a a vendedor!
03) ve al este a Silver Stream Mine alrededor de 35.19 y finish "Rat Catching": mata y saquea al Tunnel Rat enemigos (kobolds) afuera de de la mina.  And if have a group, do "Filthy Paws": saqueal Miner's League Crates dentro de la mina.  You can skip el misión if cannot get a group (but keep it aceptaed, as will be able a solo it later).
04) If did "Filthy Paws " ve al oeste y entrega up en watchtower en Algaz Station, (25.18, #2 en map).
05) Finish "Thelsamar Blood Sausages": mata boars, bears y spiders (en open fields de Loch Modan, #1 en map).
06) Hearth (if can) a Stoutlager Inn (Thelsamar) y en Inn en bar, entrega "Thelsamar Blood Sausages" 35.49.  Repara y reabastécete en.
07) In Thelsamar, find Mountaineer Kadrell /target (he patrols back y forth en town alrededor de 34.48) y entrega "Rat Catching".
 ]], }
SKquests_GuideES.Alliance[11] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) You should be nivel 12 now, if not farmea a it.
02) South en town, ve al Gryphon Master 34.51 y take a flight a Ironforge, Dun Morogh.
03) Get tu nivel 12/14 spells/abilities.
04) You can upgrade First Aid upstairs en Ironforge Physician 55.58..
05) If can afford a, can learn new weapon possibilities sur en two Weapon Masters dentro de Timberline Arms 62.89.
06) WOTLK, 10a) Go a través del Deeprun Tram 77.51.
07) WOTLK, 10b) Luego take one de two Deeprun Trams a take a Stormwind City...
08) WOTLK, 10c) Once arrive en other side de Deeprun Tram, ve al norte a través del tunnel a get into Stormwind City.
09) WOTLK, 10d) At Stormwind City, ve a Stormwind Harbor y get en boat 23.56 a take a Darkshore.
10) Once en Auberdine, follow el docks este, y en tu right acepta "For Love Eternal" (en dock, 36.44).
11) Continue este en dock hacial Inn, but go upstairs y acepta "Buzzbox 827" 37.44.
12) justo al sur del Inn, go up en platform y desdel Hippogryph Master (36.46 en Darkshore), get el Flight Path.
 ]], }
SKquests_GuideES.Alliance[12] = {title = [[Night Elf]], text = [[
01) 6 Shadowglen (Teldrassil)
02) First Pick el Class están playing top left de screen!!!
03) Along con el Game Version están playing en (Era, WotLK, or SoM)
04) frente a desde Conservator Ilthalaine, acepta "The Balance of Nature" 59.45.
05) Start working en "The Balance of Nature": mata Young Nightsabers y Young Thistle Boars alrededor del immediate area.  Work tu way hacia next steps while doing this:
06) ve al este hacia entrance de Aldrassil y acepta "The Woodland Protector" 60.42.
07) Near where started desde, en Dryad Tarindrella, entrega "The Woodland Protector" 58.45, aceptal next part.
08) Go just oeste hacia Grell camps alrededor de 56.46 y haz "The Woodland Protector": mata y saquea a Grell y Grellkin.
09) Back en Dryad Tarindrella, entrega "The Woodland Protector" (58.45 #4 en map).
10) Make sure "The Balance of Nature" está finished, luego turn it en (en starting spot 59.45, #1 en map).  acepta "The Balance of Nature" (Part2).
11) Go cerca del entrance de Aldrassil, junto a Cauldron y acepta "A Good Friend" 61.42.
12) Go en Aldrassil a get repaired/resupplied 59.41.
13) ve al oeste side de Aldrassil en bottom de ramp entrance y acepta "Webwood Venom" 58.42.
 ]], }
SKquests_GuideES.Alliance[13] = {title = [[Night Elf - Teldrassil]], text = [[
01) farmea NW a Iverron (sitting between some mountains) y entrega "A Good Friend" 55.33, acepta "A Friend in Need".
02) justo al este de, do "Webwood Venom": mata y saquea a Webwood Spiders.  A lot de spiders can be found afuera de de la cueva y more dentro de 57.32.
03) All alrededor del norte side de Shadowglen, do "The Balance of Nature": mata Mangy Nightsabers y Thistle Boars.
04) Die en purpose, luego res en Spirit Healer.
05) ve al sur hacia starting spot y desde Conservator Ilthalaine, entrega "The Balance of Nature" 59.45.
06) ve al este cerca del entrance de Aldrassil, junto a Cauldron y entrega "A Friend in Need" 61.42, acepta "Iverron's Antidote".
07) Go en Aldrassil a get repaired/resupplied 59.41.
08) ve al oeste side de Aldrassil en bottom de ramp entrance y entrega "Webwood Venom" 58.42, acepta "Webwood Egg".
09) ve al oeste hacia Grellkin camp alrededor de 55.39 y haz part de "Iverron's Antidote": mata y saquea a Grellkin or Grell paral Hyacinth Mushrooms.  NOTES:   You can also find these desde Hyacinth Mushroom objects alrededor del trees & mountains all alrededor de Shadowglen, but focus en mata y saquea aing el Grellkin para faster leveling.
10) ve al este hacia two small ponds alrededor de 58.38 y haz part de "Iverron's Antidote": saqueal Moonpetal Lily (yellow flowers) alrededor del ponds.
 ]], }
SKquests_GuideES.Alliance[14] = {title = [[Night Elf - Teldrassil]], text = [[
01) Go NW a Shadowthread Cave entrance 57.32 y haz "Webwood Egg" along con finishing "Iverron's Antidote": mata y saquea al spiders while working tu way NW en la cueva a eventually saquea a Webwood Egg.
02) usa tu Hearthstone a usa la piedra de hogar hacial starting spot.
03) ve al este cerca del entrance de Aldrassil, junto a Cauldron y entrega "Iverron's Antidote" 61.42, aceptal next part.  NOTE:  Work somewhat quickly a do el next steps as this misión está en a 5 min timer.
04) Go en Aldrassil a get repaired/resupplied 59.41.
05) ve al oeste side de Aldrassil en bottom de ramp entrance y entrega "Webwood Egg" 58.42.  acepta "Tenaron's Summons".
06) sube por ramp next a, hacia very top y luego entrega "Tenaron's Summons" 59.39, acepta "Crown of the Earth".
07) Go NW a Iverron (sitting between some mountains) y entrega "Iverron's Antidote" 55.33.
08) ve al este hacia Moonwell 60.33 y haz "Crown of the Earth": usa Crystal Phial misión item en Moonwell.
09) Die en purpose, luego res en Spirt Healer.
10) ve al top de Aldrassil (ramp entrada en 58.41, #5 en map) y entrega "Crown of the Earth", aceptal next part.
11) sigue el camino principal sur a sal de Shadowglen y de camino out, acepta "Dolanaar Delivery" 61.48.
 ]], }
SKquests_GuideES.Alliance[15] = {title = [[Night Elf - Teldrassil]], text = [[
01) 10 Dolanaar
02) sigue el camino principal a Dolanaar y de camino there, off a tu right, desde Zenn Foulhoof, acepta "Zenn's Bidding" 60.56.
03) Keep going oeste a Dolanaar y asegúrate de estar al menos a 340 XP away desde nivel 6 before getting there para aprender nuevas habilidades.  Once en Dolanaar, en bottom de la torre entrance, acepta "Denalan's Earth" 56.58.
04) Just up el ramp, acepta "A Troubling Breeze" 56.57.
05) If have 6 or more silver:  Just dentro de la torre, desdel First Aid Trainer 55.57, learn Apprentice First Aid.  NOTE:  If not, will want a make sure save tu money para spells/abilities which está more important.
06) Next a, sube por ramp hacia very top de la torre y acepta "Twisted Hatred" y "The Emerald Dreamcatcher" 55.57.
07) Drop down y entra en Inn a get repaired/resupplied 56.59.
08) sube por ramp hacia Innkeeper y entrega "Dolanaar Delivery" 56.60.  Also make Dolanaar tu new home para tu hearthstone.
09) ve al sur en Dolanaar hacia Moonwell y entrega "Crown of the Earth" 56.62, aceptal next part.   NOTE:  If están already lvl 6 right now, luego do el next step first before doing this!
 ]], }
SKquests_GuideES.Alliance[16] = {title = [[Night Elf - Teldrassil]], text = [[
01) Go SE hacia small camp en Lake Al'Ameth y entrega "Denalan's Earth" 61.68.  acepta "Timberling Seeds" y "Timberling Sprouts".
02) All alrededor de Lake Al'Ameth do "Timberling Seeds" along con "Timberling Sprouts": mata y saquea a Timberling enemigos y also saqueal Timberling Sprouts en ground.
03) vuelve al small camp en Lake Al'Ameth y entrega "Timberling Seeds" (61.68, #1 en map), acepta "Rellian Greenspyre".  Also entrega "Timberling Sprouts".
04) Start working en "Zenn's Bidding": mata y saquea a nightsabers (cats), spiders y owls.  While working en this, work tu way hacia next steps:
05) Go NE hacia Moonwell en Starbreeze Village y haz "Crown of the Earth": usa Jade Phial misión item en Moonwell 63.58.
06) sigue el camino este y go up en first building en tu right y entrega "A Troubling Breeze" 66.59, acepta "Gnarlpine Corruption".
07) entra en este most building en Starbreeze Village y haz "The Emerald Dreamcatcher": saquea Tallonkai's Dresser 68.60.
08) Finish "Zenn's Bidding": mata y saquea a nightsabers (cats), spiders y owls alrededor del open fields de Teldrassil (#4 en map).
09) ve a Zenn Foulhoof norte de main path between Dolanaar y Starbreeze Village y entrega "Zenn's Bidding" 60.56.  NOTE:  Make sure save el misión reward item para later, do not sell it a a vendedor!
10) ve al oeste a Dolanaar y en bottom de la torre entrance, acepta "Seek Redemption!" 56.58.  NOTE:  Save any Small Spider Legs  have as will usam para a later misión.
11) Just up el ramp, entrega "Gnarlpine Corruption" 56.57,
12) First Aid? 11b) If have 6 or more silver (y haven't yet):  Just dentro de la torre, desdel First Aid Trainer 55.57, learn Apprentice First Aid.  NOTE:  You can also get resupplied en la torre.  You will want a make sure save tu money para spells/abilities which está more important.
13) ve al sur en Inn a get repaired/resupplied 56.59.
14) ve al sur en Dolanaar hacia Moonwell y entrega "Crown of the Earth" 56.62, aceptal next part.
15) justo al este de en Cauldron, Learn Apprentice Cook desdel Cook 57.61.  Luego acepta "Recipe of the Kaldorei" (cooking misión).  Luego as están doing el next sections start working en this by mata y saquea aing any spiders por el camino y haz not sell el Small Spider Legs a a vendedor.  Also turn this en once get all el legs.
 ]], }
SKquests_GuideES.Alliance[17] = {title = [[Night Elf - Teldrassil]], text = [[
01) Do "Seek Redemption!": saquea 3 Fel Cones.  These están found alrededor del trees de Teldrassil.  See map para locations.
02) ve al norte de main path between Dolanaar y Starbreeze Village en Zenn Foulhoof 60.56 y entrega "Seek Redemption!".
03) If happen a have a group, continue en con el next steps (even if están lvl 7).  If están going solo, asegúrate de ser nivel 8 before proceeding, farmea en any enemigos en immediate area a nivel 8.
04) ve a Dolanaar y en Inn, get repaired/resupplied 56.59.
05) If están nivel 8, get new spells/abilities en tu class entrenaer (if haven't yet).
06) Go just norte a Fel Rock (cave entrada en 55.52), entra en la cueva y haz "Twisted Hatred": keep hugging el right side de la cueva y luego gira a la izquierda after el río, luego see if Lord Melenas /target 52.50 (an orange satyr) está standing en edge y mata y saquea a him.  If he está not there, continue hugging el right side de la cueva y will eventually get a him.  This mob can be hard a solo so be prepared.  usa Severed Voodoo Claw a help mata him.  If cannot do it, luego skip it.  Luego salida la cueva yendo hacia SE.
07) ve al bottom de tree tower en Dolanaar 55.57 a get resupplied en Danlyia, luego go up hasta lo alto de tower y entrega "Twisted Hatred" y "The Emerald Dreamcatcher", acepta "Ferocitas the Dream Eater".
08) Go NE de Starbreeze Village y haz "Ferocitas the Dream Eater": mata 7 Gnarlpine Mystics y mata y saquea a Ferocitas el Dream Eater (grey color furblog en 69.53), luego saqueal Gnarlpine Necklace that drops (en tu inventory).
09) usa la piedra de hogar hacia Dolanaar.
10) In el Inn, get repaired/resupplied y get lvl 8 spells/abilities if haven't yet.
11) Go hasta lo alto de tree tower en Dolanaar 55.57 (#7 en map) y entrega "Ferocitas the Dream Eater".
 ]], }
SKquests_GuideES.Alliance[18] = {title = [[Guía de Leveo - Sección #06]], text = [[
01) sigue el camino principal oeste until run into 3 nightelfs en their mounts (no further than 50.54), y desde Moon Priestess Amara, acepta "The Road to Darnassus".
02) Drop down a Ban'ethil Hollow alrededor de 47.53 y haz "The Road to Darnassus": mata 6 Gnarlpine Ambushers.
 ]], }
SKquests_GuideES.Alliance[19] = {title = [[Night Elf - Teldrassil]], text = [[
01) Go SW hacia Pools de Arlithrien y haz "Crown of the Earth": usa Tourmaline Phial misión item en Moonwell there 42.67.
02) SoM/WotLK, 1a) ve al sur a Gnarlpine Hold y desdel Strange Fruited Plant 43.76, acepta "The Glowing Fruit".
03) farmea tu way back hacia Dolanaar y asegúrate de estar al menos a 4,250 XP into lvl 9 before doing el next steps (or 5,050 into lvl 9 if didn't do el Den).  You can farmea en Furblogs justo al oeste de Dolanaar, or any enemigos en open fields de Teldrassil.
04) ve al norte hacia main path until run into 3 nightelfs en their mounts (no further oeste than 50.54), y desde Moon Priestess Amara, entrega "The Road to Darnassus".
05) 
06) ve al sur a Dolanaar's Inn a get repaired/resupplied 56.59.
07) South en Moonwell en Dolanaar, entrega "Crown of the Earth" 56.62, aceptal next part.
08) You should be nivel 10 right now, if not farmea a it.
 ]], }
SKquests_GuideES.Alliance[20] = {title = [[Night Elf - Teldrassil]], text = [[
01) 12 Teldrassil
02) N/A
03) N/A
04) In western Teldrassil, sigue el camino principal norte a The Oracle Glade y en end de path, off a tu right, acepta "The Enchanted Glade" (junto a Moonwell, 38.34 en Teldrassil).
05) Next a, do "Crown of the Earth": usa Amethyst Phial misión item en Moonwell there.
06) As do el following steps start working en "Tumors" by mata y saquea aing el Timberling enemigos (#6 en map):
07) ve al este past el río y see if Blackmoss el Fetid /target está there (a lvl 13 rare en alrededor de 44.30 con a 2 hour respawn) y try a mata y saquea a this mob. He drops an item, which starts "The Moss-twined Heart", acepta it.  This elemental could also be NW del río as well (en alrededor de 43.27).  NOTE:  If cannot find him, luego my guide will remind later a try again.
08) ve al norte y haz "Tears of the Moon": mata y saquea a Lady Sathrah /target (lvl 12 grey spider, has 2 spawn locations (either este 48.25 or oeste 39.25, see map).
09) Just oeste en Wellspring River (alrededor de 43.28, #6 en map), finish "Tumors": mata y saquea a Timberling enemigos.
10) ve al oeste y desdel Strange Fronded Plant (glowing red tree, 35.29), acepta "The Shimmering Frond".
11) In el immediate area do "The Enchanted Glade": mata y saquea al Bloodfeather harpies.  While doing this, work tu way hacia next step:
12) Back en harpy camp there está a black panther named Mist 32.32 that starts an escolta a misión "Mist", acepta it.
13) Make sure "The Enchanted Glade" está finished, luego lead Mist hacia Moonwell en The Oracle Glade (38.34, #4 en map) y luego entrega "The Enchanted Glade" y "Mist".  acepta "Teldrassil".
14) If need a, check again a see if Blackmoss el Fetid /target está there (a lvl 13 rare en alrededor de 44.30 or alrededor de 43.27 #7 en map).  Try a mata y saquea a this mob, he drops an item, which starts "The Moss-twined Heart", acepta it.  NOTES:  This mob has a 2 hour respawn, if cannot mata him, luego it can be skipped.
 ]], }
SKquests_GuideES.Alliance[21] = {title = [[Night Elf - Teldrassil]], text = [[
01) ve al oeste de main path en The Oracle Glade alrededor de 37.38, luego die en purpose a get a Darnassus.
02) In Darnassus, go NW a Cenarion Enclave y entrega "Tumors" (38.22 en Darnassus), acepta "Return to Denalan".
03) sigue el camino straight forward y go up en tree tower y entrega "Teldrassil" 35.9, acepta "Grove of the Ancients".
04) ve al sur en Darnassus a entra en Temple de Moon, sube por ramp, luego entrega "Tears of the Moon" 37.86, acepta "Sathrah's Sacrifice".
05) Next a, do "Sathrah's Sacrifice": drop down y usa Sathrah's Sacrifice misión item en fuente en middle de temple.
06) Go back up el ramp en Temple de Moon y entrega "Sathrah's Sacrifice" (37.86, #4 en map).
07) usa la piedra de hogar hacia Dolanaar.
08) In el Inn, get repaired/resupplied.
09) N/A
10) ve al sur hacia Moonwell en Dolanaar y entrega "Crown of the Earth" 56.62, aceptal next part.  Also entrega "Recipe of the Kaldorei" en Cook 57.61 if its finished.  If turned nivel 12, luego get new spells abilities.
11) Go SE hacia small camp en Lake Al'Ameth 61.68 y entrega (if have it) "The Moss-twined Heart", acepta (if it's available) "Planting the Heart".
12) Next a, click en Denalan's Planter a entrega (if have it) "Planting the Heart" 61.69.
13) Also entrega "The Glowing Fruit", "The Shimmering Frond" y "Return to Denalan" 61.68, acepta "Oakenscowl".  Luego, next a, click en Sprouted Frond en planter a completa "The Sprouted Fronds".
 ]], }
SKquests_GuideES.Alliance[22] = {title = [[Night Elf - Teldrassil]], text = [[
01) ve al oeste hacia small cave en Lake Al'Ameth y do "Oakenscowl": mata y saquea a Oakenscowl (lvl 9 en 54.75).
02) If did "Oakenscowl", go back este hacia small camp en Lake Al'Ameth y turn it en 61.68.
03) You should be nivel 12 by now, if not farmea en enemigos sur de Lake Al'Ameth until están.  Luego die en purpose (or run back) a Dolanaar a get new spells/abilities & repaired/resupplied.
04) First Aid? 3b) Just dentro de la torre, upgrade First Aid desdel First Aid Trainer 55.57.
05) sigue el camino principal oeste y luego just past el blue bridge alrededor de 43.51, die en purpose a get a Darnassus quicker.
06) Go NW en Darnassus y go up hasta lo alto de tree tower y entrega "Crown of the Earth" 35.9.
07) ve al sur en Darnassus y entra en el red glowing teleporter 28.42.
08) Once en Rut'theran Village, baja por path y entrega "Nessa Shadowsong" (56.92 en Teldrassil), acepta "The Bounty of Teldrassil".
09) ve al este en el puente hacia Hippogryph Master y entrega "The Bounty of Teldrassil" 58.94, acepta "Flight to Auberdine".  Luego take a ride a Auberdine, Darkshore.
10) Go down en Inn en Auberdine y entrega "Flight to Auberdine" 37.44, acepta "Return to Nessa".
11) Go back up hacia Hippogryph Master 36.46 en Auberdine y fly a Rut'theran Village, Teldrassil.
12) ve al oeste past el puente a bit y entrega "Return to Nessa" (56.92 en Teldrassil).
13) Go back este en el puente hacia Hippogryph Master 58.94 y fly a Auberdine, Darkshore.
 ]], }
SKquests_GuideES.Alliance[23] = {title = [[Gnome/Dwarf]], text = [[
01) 6 Coldridge Valley (Dun Morogh)
02) First Pick el Class están playing top left de screen!!!
03) Along con el Game Version están playing en (Era, WOTLK, or SoM)
04) frente a desde Sten Stoutarm, acepta "Dwarven Outfitters" 30.72.
05) Just hacia sur de, do "Dwarven Outfitters": mata y saquea a wolves alrededor de 29.74.
06) Vendor, 2a) vuelve al starting spot y get resupplied (vende la basura) 30.72.
07) Next a, acepta "A New Threat" 30.71.
08) As do el following steps start working en "A New Threat": mata Rockjaw Troggs y Burly Rockjaw Troggs:
09) Go SW en small camp/tent y entrega "Coldridge Valley Mail Delivery" 23.71, aceptal next part.  Also acepta "The Boar Hunter".
10) Just oeste y norte de do "The Boar Hunter": mata Small Crag Boars.
11) vuelve al small camp/tent y entrega "The Boar Hunter" (23.71, #6 en map).
 ]], }
SKquests_GuideES.Alliance[24] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) sigue el camino principal SE hacia small dwarf camp y entrega "Coldridge Valley Mail Delivery" 25.76, acepta "The Troll Cave".
02) Around southern Coldridge Valley, start working en "The Troll Cave": mata Frostmane Troll Whelps.  There está a lot en la cueva al sur (entrada en 27.80).  As soon as hit nivel 4, stop what están doing y go do el following steps:
03) ve al dwarf camp sur en main path y acepta "Scalding Mornbrew Delivery" 25.76.  NOTE:  This misión has a 5 min time limit, as long as do not go AFK or something should have plenty de time a get this en.
04) usa la piedra de hogar hacial starting spot.
05) ve al norte y entra en Anvilmar luego acepta "A Refugee's Quandary" patrols a bit 29.68.  Next a, repara y reabastécete en 29.68.
06) ve al norte en Anvilmar y entrega "Scalding Mornbrew Delivery" 29.66.  acepta "Bring Back the Mug".
07) In Anvilmar, get tu nivel 4 class's spells/abilities.
08) Exit Anvilmar sur, luego finish "A New Threat": mata Rockjaw Troggs (mostly este alrededor de 31.75) y Burly Rockjaw Troggs (mostly oeste).
09) At el starting spot, entrega "A New Threat" 30.71.  Repara y reabastécete en (desdel blue shirted dwarf under red tent) 30.72.
10) ve al sur hacia small dwarf camp en end de main path y entrega "Bring Back the Mug" (25.76, #3 en map).
 ]], }
SKquests_GuideES.Alliance[25] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) ve al oeste y haz "A Refugee's Quandary": saqueal 3 objects en troll camps.  First saquea Felix's Box (frente a Campfire, 21.76).  See next steps paral other two:
02) saquea Felix's Chest (junto a Campfire, 23.80).
03) saquea Felix's Bucket de Bolts (frente a Campfire, 26.79).
04) Around southern Coldridge Valley, finish "The Troll Cave": mata Frostmane Troll Whelps.  There está a lot en la cueva al sur (entrada en 27.80).
05) vuelve al dwarf camp sur en main path y entrega "The Troll Cave" 25.76, acepta "The Stolen Journal".
06) Go SE y entra en el troll cave (entrada en 27.80, #4 en map) y haz "The Stolen Journal": keep hugging el left side de la cueva until get a Grik'nir el Cold /target 30.80 y mata y saquea a this troll.
07) Go NW hacia small dwarf camp en end de main path y entrega "The Stolen Journal" (25.76, #5 en map), acepta "Senir's Observations".
08) Hearth (if can), or die en purpose a get hacia starting spot.
09) ve al norte a entra en Anvilmar luego entrega "A Refugee's Quandary" patrols a bit 29.68.  Repara y reabastécete en 29.68.
10) Exit Anvilmar (sur) luego head este en main path hacia entrance de Coldridge Pass y entrega "Senir's Observations" 33.72, aceptal next part.
11) Just next a up el hill, acepta "Supplies to Tannok" 34.72.
12) entra en Coldridge Pass next a (entrada en 34.71) y work tu way a través de it.
 ]], }
SKquests_GuideES.Alliance[26] = {title = [[8 Dun Morogh]], text = [[
01) Go NE a Kharanos y asegúrate de estar al menos a 450 XP away desde lvl 6 before getting there para aprender nuevas habilidades.  Just sur en Kharanos, off a tu right, entrega "Senir's Observations" 46.54.
02) ve al norte into Kharanos y off a tu right, acepta "Beer Basted Boar Ribs" 47.52.
03) Next a, entra en Thunderbrew Distillery (el Inn) y entrega "Supplies to Tannok" 47.52.
04) Next hacia fireplace, desdel Physician, learn Apprentice First Aid 47.53.
05) Next a by el bar, desde Innkeeper Belm 47.53, talk a him a make Thunderbrew Distillery tu new home para tu Hearthstone.  Make sure están resupplied.  NOTE:  Do not sell any Crag Boar Ribs  may have.
06) Across desde Thunderbrew Distillery, en entrance de blacksmith shop, acepta "Tools for Steelgrill" 46.52.
07) Go NE a Steelgrill's Depot 49.48 y acepta "Stocking Jetsteam", y next a "The Grizzled Den".
08) Just hacia este between el two huts, acepta "Ammo for Rumbleshot" 50.49.
09) frente al hut, entrega "Tools for Steelgrill" 50.49.
 ]], }
SKquests_GuideES.Alliance[27] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) As work en following steps also start working en "Beer Basted Boar Ribs" along con "Stocking Jetsteam" by mata y saquea aing boars y bears scattered all alrededor de Dun Morogh (also do not sell el misión items a a vendedor!):
02) SW de Kharanos, do "Ammo for Rumbleshot": saqueal Ammo Crate junto a tent/Campfire 44.57.
03) ve al norte a bit y haz "The Grizzled Den": mata y saquea a Yetis.  You can find a lot more en Den (entrada en 42.54).
04) ve al sur hacia small dwarf camp along el main path y entrega "Ammo for Rumbleshot" 41.65.  Repara y reabastécete en.  Do NOT sell tu misión items!
05) Just norte en open fields de Dun Morogh, finish "Beer Basted Boar Ribs" along con "Stocking Jetsteam": mata y saquea a boars y bears.  Focus mostly en Crag Boars.  NOTE:  You will get el Rhapsody Malt later.
06) Make sure están en least 625 XP away desde nivel 7, luego usa la piedra de hogar hacia Thunderbrew Distellery (or run back if están already close).
07) Desde Innkeeper Belm 47.52, purchase a Rhapsody Malt desde him para "Beer Basted Boar Ribs".  Make sure están resupplied (Do NOT sell tu misión items!).
08) justo afuera del Inn, entrega "Beer Basted Boar Ribs" 47.52.  You should be lvl 7 now, if not farmea a it.
09) South de Kharanos, junto a tent/carreta, acepta "Frostmane Hold" 47.54.
10) North en Kharanos, down en goblin hut, acepta "Operation Recombobulation" 46.49.
11) ve al este a Steelgrill's Depot 49.48 y entrega "Stocking Jetsteam", acepta "Evershine".  And next a entrega "The Grizzled Den".
 ]], }
SKquests_GuideES.Alliance[28] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) ve al oeste (take el sur route) y sube por mountain (entrada en 36.53)..
02) Up el mountain, acepta "Tundra MacGrann's Stolen Stash" 35.52.
03) ve al este back down el mountain y try a do "Tundra MacGrann's Stolen Stash": In la cueva saquea MacGrann's Meat Locker 38.51 y watch out paral lvl 11 patrolling elite yeti.  You can simply wait para this elite yeti a sal de la cueva luego run en there a saquea it, although he stays en la cueva para several minutes en a time.  Try a group if can a take him en, or can skip it or try later (as will pass this spot a few more times later) y it gets turned en back up el hill junto a cave.
04) Back up el mountain, entrega (if did it) "Tundra MacGrann's Stolen Stash" (35.52, #2 en map).
05) Go NW a Brewnall Village y entrega "Evershine" 30.46, acepta "A Favor for Evershine".  Also acepta "The Perfect Stout".
06) Next a, acepta "Bitter Rivals" 30.24.
07) You can get resupplied desde Keeg Gibn under el red canopy 30.45.
08) While doing el next steps, start working en "A Favor for Evershine" by mataing el Ice Claw Bears, Elder Crag Boars y Snow Leopards alrededor del western open fields de Dun Morogh:
09) Go NE up a Shimmer Ridge (entrada en 38.42) y haz "The Perfect Stout": mata y saquea a Frostmane Seers y saquea Shimmerweed Baskets.
10) ve al oeste a Brewnall Village y entrega "The Perfect Stout" (30.46, #5 en map), luego if están lvl 8 acepta "Shimmer Stout".  And get resupplied.
11) All alrededor de western Dun Morogh (past Iceflow Lake) continue working en "A Favor for Evershine" by mataing el Ice Claw Bears, Elder Crag Boars y Snow Leopards (#7 en map).  Once hit nivel 8, Hearth, or just vuelve a Kharanos.
 ]], }
SKquests_GuideES.Alliance[29] = {title = [[10 Dun Morogh]], text = [[
01) In Thunderbrew Distillery (el Inn), en Innkeeper Belm 47.52, purchase a Thunder Ale.  Make sure están resupplied.
02) baja por steps en Thunderbrew Distillery hacia room con all el barriles 48.53 y haz "Bitter Rivals": talk a Jarven Thunderbrew next a a give him el Thunder Ale.  Wait a few seconds, luego click en Unguarded Thunder Ale Barrel a entrega "Bitter Rivals", acepta "Return to Marleth".
03) Find tu class entrenaer alrededor de Kharanos y learn tu nivel 8 spells/abilities.
04) ve al oeste a Brewnall Village 30.46 y entrega "Return to Marleth".  Also acepta (if haven't yet) "Shimmer Stout".
05) Go SW a entra en Frostmane Hold (entrada en 25.51)..
06) Do "Frostmane Hold": work tu way hacia middle de la cueva 23.52 a get it explored.  Also mata 5 Frostmane Headhunters.
07) sal de la cueva luego go al norte hacia entrance de Gnomeregan alrededor de 25.44 y haz "Operation Recombobulation": mata y saquea al Leper Gnomes.
 ]], }
SKquests_GuideES.Alliance[30] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) All alrededor de western Dun Morogh (past Iceflow Lake) finish "A Favor for Evershine": mata Ice Claw Bears, Elder Crag Boars y Snow Leopards alrededor del open fields de Dun Morogh.
02) ve a Brewnall Village y entrega "A Favor for Evershine" 30.46, acepta "Return to Bellowfiz".
03) Go a Kharanos y sur en town, entrega "Frostmane Hold" 47.54, acepta "The Reports".  Repara y reabastécete en.
04) North en Kharanos, down en goblin hut, entrega "Operation Recombobulation" 46.49.
05) Go NE a Steelgrill's Depot y entrega "Return to Bellowfiz" 49.48.
06) At this point it está wise a get tu nivel 10 spells/abilities before continuing, so farmea en any enemigos en open fields de Dun Morogh until están nivel 10.  If still have a ways a go before 10, can ve al este y aceptal two misiones "The Public Servant" y "Those Blasted Troggs!" 69.56 y start working en them by mataing el Rockjaw Skullthumpers en Gol'Bolar Quarry alrededor de 68.59 .  You can also try a matal Rockjaw Bonesnappers en la cueva (entrada en 71.56).  Turn these en if completa them.
 ]], }
SKquests_GuideES.Alliance[31] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) 11 Dun Morogh
02) sigue el camino principal este a Gol'Bolar Quarry y finish (if still need a) "Those Blasted Troggs!" by mataing el Rockjaw Skullthumpers en Gol'Bolar Quarry alrededor de 68.59 y "The Public Servant" by mataing Rockjaw Bonesnappers en la cueva (entrada en 71.56).  These misiones están aceptaed en Quarry there!
03) Go back up y entrega "The Public Servant" 69.56.
04) Next a, detrás del tent, entrega "Those Blasted Troggs!" 69.56.
05) ve al norte a Amberstill Ranch y acepta "Protecting the Herd" 63.50.
06) Just hacia oeste de está a hidden path that leads up el mountain, go up it luego head norte y haz "Protecting the Herd": mata y saquea a Vagash /target alrededor de 62.34.  This lvl 11 Yeti patrols up alrededor del mountain ledges.  This can be skipped if it gives troubles.
07) Back en Amberstill Ranch, entrega "Protecting the Herd" (63.50, #4 en map).
08) sigue el camino NE a North Gate Outpost y acepta "The Lost Pilot" 84.39.
09) Go NW a bit y click en A Dwarven Corpse a entrega "The Lost Pilot" 80.36, acepta "A Pilot's Revenge".
10) Go just SW up el path a bit y haz "A Pilot's Revenge": mata y saquea a Mangeclaw /target 78.38.
11) Back este en Outpost entrega "A Pilot's Revenge" (84.39, #7 en map).
12) ve al South Gate Outpost y entrega "Shimmer Stout" 86.49, acepta "Stout to Kadrell".
13) entra en South Gate Pass (entrada en 17.59) y go a través de it a get a Loch Modan..
 ]], }
SKquests_GuideES.Alliance[32] = {title = [[12 Loch Modan]], text = [[
01) Once entra en Loch Modan  will arrive en Valley de Kings, y frente a watchtower, acepta "In Defense of the King's Lands" (22.73 en Loch Modan).
02) Go up en watchtower frente a y acepta "The Trogg Threat" 23.74.
03) sigue el camino principal NE, luego gira a la derecha a ve a Stonesplinter Valley alrededor de 32.73 y haz "In Defense of the King's Lands" along con "The Trogg Threat": mata 10 Stonesplinter Troggs y 10 Stonesplinter Scouts, y saquea them paral Stone Tooth.
04) Go back oeste a Valley de Kings y entrega "In Defense of the King's Lands" (22.73, #1 en map).
05) Go up en watchtower y entrega "The Trogg Threat" 23.74.
06) ve al norte a Thelsamar alrededor de 34.48 y find Mountaineer Kadrell (he patrols back y forth en town) y entrega "Stout to Kadrell".  Desde him acepta "Rat Catching" y "Mountaineer Stormpike's Task".
07) entra en Inn (el building con el big barriles alrededor de it), (entrada en 35.48).. y el first NPC see (Innkeeper Hearthstove, 35.48), talk a him a make this Inn tu new home.
08) At el bar, desde Vidra Hearthstove, acepta "Thelsamar Blood Sausages" 35.49.  Make sure están resupplied.  If need 6 slot bags, can purchase them desdel General Supplies vendedor en Inn (if can afford them).
 ]], }
SKquests_GuideES.Alliance[33] = {title = [[Alliance - Loch Modan]], text = [[
01) While working tu way norte hacia next steps, also start working en "Rat Catching" by mata y saquea aing Tunnel Rat enemigos (kobolds) along el oeste side de main path (#3 en map).  Also start working en "Thelsamar Blood Sausages" by mataing boars, bears y spiders (en open fields de Loch Modan, #1 en map):
02) farmea norte a Algaz Station, go up en watchtower y entrega "Mountaineer Stormpike's Task" 25.18, acepta "Stormpike's Order".  Also acepta "Filthy Paws".  NOTE:  You can get repaired/resupplied en bottom de watchtower but do not sell tu "Thelsamar Blood Sausages" misión items a a vendedor!
03) ve al este a Silver Stream Mine alrededor de 35.19 y finish "Rat Catching": mata y saquea al Tunnel Rat enemigos (kobolds) afuera de de la mina.  And if have a group, do "Filthy Paws": saqueal Miner's League Crates dentro de la mina.  You can skip el misión if cannot get a group (but keep it aceptaed, as will be able a solo it later).
04) If did "Filthy Paws " ve al oeste y entrega up en watchtower en Algaz Station, (25.18, #2 en map).
05) Finish "Thelsamar Blood Sausages": mata boars, bears y spiders (en open fields de Loch Modan, #1 en map).
06) Hearth (if can) a Stoutlager Inn (Thelsamar) y en Inn en bar, entrega "Thelsamar Blood Sausages" 35.49.  Repara y reabastécete en.
07) In Thelsamar, find Mountaineer Kadrell (he patrols back y forth en town) y entrega "Rat Catching".
08) East en Thelsamar, down en hut, acepta "Honor Students" 37.48 .
 ]], }
SKquests_GuideES.Alliance[34] = {title = [[17 Darkshore]], text = [[
01) You should be nivel 12 now, if not farmea a it.
02) South en town, ve al Gryphon Master 34.51 y entrega "Honor Students", acepta "Ride to Ironforge".  Luego take a flight a Ironforge, Dun Morogh.
03) In Ironforge, ve al norte a Deep Mountain Mining Guild y entrega "Ride to Ironforge" 51.26, acepta "Gryth Thurden".
04) ve al Gryphon Master 55.48 y entrega "Gryth Thurden", acepta "Return to Brock".  Luego take a flight a Thelsamar, Loch Modan.
05) East en Thelsamar, down en hut, entrega "Return to Brock" 37.48.
06) South en town, ve al Gryphon Master (34.51, #2 en map) y take a flight a Ironforge, Dun Morogh.
07) You can upgrade First Aid upstairs en Ironforge Physician 55.58..
08) If can afford a, can learn new weapon possibilities sur en two Weapon Masters dentro de Timberline Arms 62.89.
09) WOTLK, 13a) Go a través del Deeprun Tram 77.51, y luego between el two Tram track acepta "Deeprun Rat Roundup".
10) WOTLK, 13b) Just alrededor del immediate area do "Deeprun Rat Roundup": usa Rat Catcher's Flute misión item en Deeprun Rats.
11) WOTLK, 13c) Go back between el two tracks en Deeprun Tram, y entrega "Deeprun Rat Roundup", acepta "Me Brother, Nipsy".
12) WOTLK, 13d) Luego take one de two Deeprun Trams a take a Stormwind City.
13) WOTLK, 13e) Once arrive en other side de Deeprun Tram, entrega "Me Brother, Nipsy" between el two tram tracks.  Luego ve al norte a través del tunnel a get into Stormwind City.
14) WOTLK, 13f) At Stormwind City, ve a Stormwind Harbor y get en boat 23.56 a take a Darkshore.
15) Once en Auberdine, follow el docks este, y en tu right acepta "For Love Eternal" (en dock, 36.44).
16) Continue este en dock hacial Inn, but go upstairs y acepta "Buzzbox 827" 37.44.
17) justo al sur del Inn, go up en platform y desdel Hoppogryph Master (36.46 en Darkshore), get el Flight Path.
18) 12+
19) First Pick el Class están playing top left de screen!!!
20) Along con el Game Version están playing en (Era, SoM, TBC or WotLK)
21) At Auberdine en Hippogryph dock, acepta "Washed Ashore" 37.46.
22) entra en Inn y desde Innkeeper Shaussiy 37.44, make Auberdine tu new home.  NOTE:  Desdel Fish Vendor /target en Inn can purchase Longjaw Mud Snapper, which está a cheap tier 2 food.
23) NIGHT ELF ONLY (other races should have already did this):  ve al oeste de Inn en long docks y acepta "For Love Eternal" 36.44.
24) NIGHT ELF ONLY (other races should have already did this):  vuelve award el Inn, but go upstairs y acepta "Buzzbox 827" 37.44.
25) justo afuera del Inn, junto a mailbox, acepta "Cave Mushrooms" 37.44.
26) Just cruzando el path desde cerca del moonwell, acepta "The Red Crystal" 38.43.
27) ve al norte cruzando el puente y into el merchant building luego acepta "Bashal'Aran" y "Tools of the Highborne" 37.40.
28) GET BAGS:  At this point if do not have all 6 slot bags it está highly recommended a compra them desdel General Goods (37.40, /target) vendedor en merchant building, as long as can afford them.
29) Take el SE bridge hacia other building y en entrance, acepta "Plagued Lands" 39.43.
30) Go dentro del building y acepta "How Big a Threat?" 39.43.
31) Work tu way al sur along el shore while doing "Buzzbox 827": mata y saquea a crabs.  Work tu way hacia Beached Sea Creature 36.51 y click en it a saqueal Sea Creature Bones para "Washed Ashore".
32) Go back norte a Auberdine y junto a Hippogryph dock, off en grass, desde Buzzbox 827 (37.46, #1 en map), entrega "Buzzbox 827", acepta "Buzzbox 411".
33) On el Hippogryph dock, entrega "Washed Ashore" 37.46, aceptal next part.
34) ve al oeste out en sea y haz "Washed Ashore": saqueal Skeletal Sea Turtle's head 32.46.
35) Around en sea do "Buzzbox 411": mata y saquea a Darkshore Threshers /target.
 ]], }
SKquests_GuideES.Alliance[35] = {title = [[Alliance - Darkshore]], text = [[
01) vuelve a Auberdine en Hippogryph dock y entrega "Washed Ashore" 37.46.
02) In el town, get repaired/resupplied 37.44.
03) ve al norte hacia shore, en Beached Sea Creature 42.31 y click en it a acepta "Beached Sea Creature".
04) ve al norte along el shore y en Buzzbox 411 42.29, entrega "Buzzbox 411", acepta "Buzzbox 323".
05) As work tu way a do el next steps, start working en "Buzzbox 323" by mata y saquea aing el Moonstalkers (cats):
06) ve al sur a Bashal'Aran, up en hill, en blue mist, entrega "Bashal'Aran" 44.36, aceptal next part.
07) justo al sur de where están en alrededor de 45.37, do "Bashal'Aran": mata y saquea a Vile Sprites y Wild Grell.
08) Go back up en hill en Bashal'Aran, en blue mist, entrega "Bashal'Aran" (44.36, #6 en map), aceptal next part.
09) justo al sur de where están en alrededor de 45.37, do "Bashal'Aran": mata y saquea a Deth'ryll Satyr /target (orange colored patrolling satyr).
10) Go back up en hill en Bashal'Aran, en blue mist, entrega "Bashal'Aran" (44.36, #6 en map), aceptal next part.
11) farmea al sur y en top de hill, simply run up close hacia Mysterious Red Crystal 47.49 para "The Red Crystal".
12) ve al oeste cruzando el main path into el furbolg camp 40.54 a simply get it discovered para "How Big a Threat?".
13) Go al sur en main path y acepta "The Fall of Ameth'Aran" 40.60.
 ]], }
SKquests_GuideES.Alliance[36] = {title = [[Alliance - Darkshore]], text = [[
01) ve al este en Ameth'Aran y start working en "Tools of the Highborne": mata y saquea al Highborne enemigos (apparitions).  While doing this, also work tu way a do el next steps:
02) Do part de "The Fall of Ameth'Aran": junto a old dark gazebo, click The Lay de Ameth'Aran 43.59 white tablet laying en ground.
03) ve al sur hacia other gazebo y haz "Bashal'Aran": click en Ancient Flame 42.62.  Also do "For Love Eternal": find y mata y saquea a Anaya Dawnrunner /target, she patrols clockwise alrededor de this gazebo.
04) ve al sur a bit more y haz el last part de "The Fall of Ameth'Aran": click en The Fall de Ameth'Aran tablet standing upright 43.63.
05) Make sure "Tools of the Highborne" está finished:  mata y saquea al Highborne enemigos (apparitions, #1 en map) alrededor de Ameth'Aran.
06) Make sure están en least 6,000 XP into nivel 13 before continuing.  farmea en Highborne enemigos (apparitions) alrededor de Ameth'Aran until están.
07) ve al oeste hacia main path y entrega "The Fall of Ameth'Aran" 40.60.
08) To el oeste de main path do "Plagued Lands": usa Tharnariun's Hope misión item en a Rabid Thistle Bear /target alrededor de 39.60.  NOTE:  Make sure están en range y en clear view de mob when using el misión item, otherwise might miss y will have a vuelve a Auberdine a get a new one.
 ]], }
SKquests_GuideES.Alliance[37] = {title = [[Night Elf - Teldrassil]], text = [[
01) usa la piedra de hogar hacia Auberdine.  Repara y reabastécete en.
02) ve al oeste de Inn en long docks y entrega "For Love Eternal" 36.44.
03) justo afuera del Inn y cruzando el path by el moonwell, entrega "The Red Crystal" 38.43, acepta "As Water Cascades".
04) usa Empty Water Tube misión item en moonwell next a  38.44.
05) ve al este cruzando el puente y en entrance hacia building, entrega "Plagued Lands" 39.43, acepta "Cleansing of the Infected".
06) entra en building y entrega "How Big a Threat?" 39.43, aceptal next part.  Also acepta "Thundris Windweaver".
07) Go up en building y acepta "The Tower of Althalaxx" 39.44.
08) Take el puente going norte y en dwarf area by el carreta, acepta "Deep Ocean, Vast Sea" 38.41.
09) entra en merchant building next a  37.40 y entrega "Tools of the Highborne" y "Thundris Windweaver", acepta "The Cliffspring River".
10) ve al Hippogryph dock (sur de Inn) y entrega "Beached Sea Creature" 37.46.
11) You should be nivel 14 now.  If están a Mage, Paladin, Hunter, Priest, Rogue or Warrior y could benefit desde getting tu nivel 14 spells/abilities, luego can do that now en Darnassus.    El other classes can take el boat 32.44 a Stormwind a get their spells/abilities.  So if can benefit desde getting tu lvl 14 abilities, Night Elves can take a Hippogryph ride desdel Hippogryph Master next a.  If están dwarf, gnome or human will have a take el Boat a Teldrassil 33.40, luego a get back a Auberdine take el punto de vuelo (en 58.94 en Teldrassil).
 ]], }
SKquests_GuideES.Alliance[38] = {title = [[Alliance - Darkshore]], text = [[
01) As work en following steps start working en "Cleansing of the Infected" by mataing el Rabid Thistle Bears.  Also continue working en "Buzzbox 323" by mata y saquea aing el Moonstalkers (cats):
02) ve al norte a Bashal'Aran, up en hill, en blue mist, entrega "Bashal'Aran" 44.36.
03) Go NW out en sea y haz "Deep Ocean, Vast Sea": saqueal two chests en two sunken boats.  First one, go under el boat y entra en el crack en bottom de boat (entrada en 39.29), luego head NW en boat y saqueal Silver Dawning's Lockbox 38.29:
04) Head NE y entra en el bottom de other boat 40.27, luego head oeste en boat y saqueal Mist Veil's Lockbox 40.27.
05) Go NE en shore y click en Beached Sea Turtle's arm 44.21 a acepta "Beached Sea Turtle".
06) justo al sur de en open fields de Darkshore, finish "Buzzbox 323" by mata y saquea aing el Moonstalkers /target (cats, #1 en map).
07) sigue el camino principal este y just past el puente en tu left está Buzzbox 323 51.25, desde it entrega "Buzzbox 323", acepta "Buzzbox 525".
08) Next a, drop down en bottom de waterfall y haz "The Cliffspring River": usa Empty Sampling Tube misión item en bottom de waterfall 51.26.
 ]], }
SKquests_GuideES.Alliance[39] = {title = [[Alliance - Darkshore]], text = [[
01) ve al sur y up en hill, click en Mysterious Red Crystal 47.49 a entrega "As Water Cascades", acepta "The Fragments Within".
02) Go SW past el main path hacia furbolg camp alrededor de 40.54 y haz "How Big a Threat?": matal required amount de Blackwood furbolgs.
03) Work tu way al sur while mataing Rabid Thistle Bears (#7 en map) para "Cleansing of the Infected".  Eventually make tu way hacia shoreline en Beached Sea Turtle 37.62 y click en its head a acepta "Beached Sea Turtle".
04) Continue al sur while mataing Rabid Thistle Bears (#7 en map) para "Cleansing of the Infected".  Eventually make tu way hacia shoreline en Beached Sea Creature 36.71 y click el body a acepta "Beached Sea Creature".
05) ve al sur hacia Beached Sea Creature 33.81 y click where el neck meets el body a acepta "Beached Sea Creature".
06) If have "Grove of the Ancients":  Turn this en en Onu big tree NPC, 44.76.
07) East de alrededor del open fields de Darkshore alrededor de 38.71 finish "Cleansing of the Infected": mata Rabid Thistle Bears.  Also start working en "Buzzbox 525" by mata y saquea aing Grizzled Thistle Bears.
08) Go al sur alrededor de 40.81 y finish "Buzzbox 525": mata y saquea a Grizzled Thistle Bears (#7 en map).
09) Just right off el main path ve a Buzzbox 525 41.81 y entrega "Buzzbox 525".
 ]], }
SKquests_GuideES.Alliance[40] = {title = [[Alliance - Darkshore]], text = [[
01) Keep farmeaing until están 6,370 XP3,550 XP into nivel 15, luego usa la piedra de hogar hacia Auberdine.
02) ve al Hippogryph dock (sur de Inn, 37.46) y entrega ALL "Beached Sea" misiones may have.
03) Go below el Hippogryph dock, junto a shore y acepta "Fruit of the Sea" 36.45.  NOTE:  "The Family and the Fishing Pole" está a fishing misión that takes too much time para XP y I recommend skipping it.  If están bored y want a learn fishing or do something different can give it a try.
04) Just cruzando el path desde, cerca del moonwell, entrega "The Fragments Within" 38.43.
05) Take el puente norte y justo afuera del merchant building (a tu left), acepta "The Absent Minded Prospector" 37.42.
06) entra en merchant building next a y entrega "The Cliffspring River" 37.40, acepta "The Blackwood Corrupted" (requires lvl 15).  Repara y reabastécete en.
07) justo afuera del building en dwarf camp junto a carreta, entrega "Deep Ocean, Vast Sea" 38.41.
08) Take el SE bridge hacia other building y en entrance, entrega "Cleansing of the Infected" 39.43, acepta "Tharnariun's Hope".
09) entra en building y entrega "How Big a Threat?" 39.43.  acepta "A Lost Master".
10) ve al moonwell en Auberdine y usa tu Empty Cleansing Bowl misión item en it 38.44.
11) You should be nivel 16 by now:  If están a Mage, Paladin, Druid, Priest, Rogue or Warrior y could benefit desde getting tu nivel 16 spells/abilities, can do that now en Darnassus.  El other classes can take el boat 32.44 a Stormwind a get their spells/abilities.  So if can benefit desde getting tu lvl 16 abilities, can take a Hippogryph ride desdel Hippogryph Master 36.46 or might need a take el boat en docks.  Luego hearth (or fly back) a Auberdine.
 ]], }
SKquests_GuideES.Alliance[41] = {title = [[Guía de Leveo - Sección #07]], text = [[
01) Go NE y haz part de "The Blackwood Corrupted": saqueal Blackwood Grain Stores 51.35.
02) Go up hacia small cave (path entrada en 53.37).  Once up there do "Tharnariun's Hope": mata Den Mother.
03) Go NE a bit hacia other furbolg camp y finish "The Blackwood Corrupted": saqueal Blackwood Nut Stores 52.33.  See next steps para what else a do:
04) On el other side de this camp, saqueal Blackwood Fruit Stores 53.33.
05) usa Filled Cleansing Bowl misión item en Bonfire en middle del campamento 52.33.  mata Xabraxxis (lvl 19) that spawns, luego saquea Xabraxxis' Demon Bag that spawns en ground.  NOTES: You can usa Filled Cleansing Bowl 20 yards away desdel Bonfire y when do it will make friendly con all el furblogs en el campamento para a minute giving an easier chance a matal lvl 19 satyr.
06) ve al sur, luego up y a través del waterfall frente a cave (path entrada en 55.32) y haz "Cave Mushrooms": saqueal mushrooms en ground en la cueva.  NOTE:  This can be hard a solo para some classes (rogues, warriors, etc), en that case try a get help or el guide will remind once more a come back here once están stronger later en (but it will be a tad off route).
07) Go NE y just off el main path next a a rock, entrega "The Tower of Althalaxx" 55.25, aceptal next part.
08) Go SE a bit (alrededor de la torre, 55.27) y haz "The Tower of Althalaxx": mata y saquea a Dark Strand Fanatics (female humans).  Warning:  Do NOT go dentro de la torre, as there está higher nivel enemigos en there!
09) Back just off el main path next a a rock, entrega "The Tower of Althalaxx" (55.25, #7 en map), aceptal next part.
10) ve al norte hacia shore y click en Beached Sea Turtle's head 53.18 a acepta "Beached Sea Turtle".
11) Work tu way oeste along el shore y haz "Fruit of the Sea": mata y saquea a Encrusted Tide Crawlers (higher lvl crabs) y Reef Crawlers (lower lvl crabs more oeste).
 ]], }
SKquests_GuideES.Alliance[42] = {title = [[Gnome/Dwarf - Dun Morogh]], text = [[
01) usa la piedra de hogar hacia Auberdine.  If hearthstone está still en a cooldown, luego die en purpose, res en spirit, luego go a Auberdine.  If  died en purpose, luego entregal following 5 misiones en reverse:
02) Go below el Hippogryph dock, junto a shore y entrega "Fruit of the Sea" 36.45.
03) ve al Hippogryph dock (sur de Inn) y entrega "Beached Sea Turtle" 37.46.
04) justo afuera del Inn, junto a mailbox, entrega "Cave Mushrooms" 37.44, acepta "Onu".
05) Take el norte bridge y en merchant building, entrega "The Blackwood Corrupted" 37.40.  Repara y reabastécete en.
06) Take el SE bridge hacia other building y en entrance, entrega "Tharnariun's Hope" 39.43.
07) Out en long docks, tomal barco a Stormwind City 32.44.
08) El goal now está a get a Loch Modan a continue questing.  If están a Dwarf, Gnome or Human luego ve al Gryphon Master 71.73 y fly a Thelsamar, Loch Modan, luego skip hacia Loch Modan section below!  Night Elves will have a much longer journey, so if están a Night Elf, follow el steps below:
09) NIGHT ELF ONLY:  Go NE en Dwarven District a entra en el Deeprun Tram 69.31.  Luego wait paral tram ride a show up y it will take a Ironforge's side de Deeprun Tram.
10) NIGHT ELF ONLY:  Once en other side de Deeprun Tram, acepta "Deeprun Rat Roundup" (this está aceptaed between el two Tram tracks).
11) NIGHT ELF ONLY:  Just alrededor del immediate area do "Deeprun Rat Roundup": usa Rat Catcher's Flute misión item en Deeprun Rats.
12) NIGHT ELF ONLY:  Go back between el two tracks en Deeprun Tram, y entrega "Deeprun Rat Roundup".  NOTE:  "Me Brother, Nipsy" will be skipped para now.
13) NIGHT ELF ONLY:  Exit el Deeprun Tram yendo hacia norte a través del tunnel..
14) NIGHT ELF ONLY:  At Ironforge get el Flight Path desdel Gryphon Master 55.48.
15) NIGHT ELF ONLY:  Exit Ironforge sur 16.85.
16) NIGHT ELF ONLY:  Run all el way este a través de Dun Morogh hacia South Gate Pass 82.53 y go a través de it. Luego go a través del other tunnel de South Gate Pass 17.59.
 ]], }
SKquests_GuideES.Alliance[43] = {title = [[18 Loch Modan]], text = [[
