SKquests_GuideES.Alliance[45] = {title = [[Alliance - Loch Modan]], text = [[
01) Go NW hacia entrance de Stonewrought Dam, go dentro de y can get repaired/resupplied 41.13.  Be careful not a sell tu Crocolisk Meat a a vendedor!
