 ]], }
SKquests_GuideES.Alliance[50] = {title = [[Guía de Leveo - Sección #04]], text = [[
01) sigue el camino principal este into Astranaar, gira a la izquierda after el blue bridge y get el Flight Path desdel Hippogryph Master 34.48.
02) Along el main path as entra en el town, acepta "The Zoram Strand" 35.49.
