SKquests_GuideES.Alliance[53] = {title = [[23 Stonetalon Mountains]], text = [[
01) farmea SW hacia goblin en hut y acepta "Super Reaper 6000" 59.63.  NOTE:  Start working en "Pridewings of Stonetalon" by mata y saquea aing any Pridewing enemigos (wyverns, #7 en map) see por el camino.
