 ]], }
SKquests_GuideES.Alliance[62] = {title = [[Alliance - Wetlands]], text = [[
01) Go upstairs en Inn (en middle room) y entrega "The Absent Minded Prospector" 11.60.  REMINDER:  El First Aid Trainer 11.61 está en other room upstairs if need a upgrade First Aid.
