SKquests_GuideES.Alliance[99] = {title = [[Guía de Leveo - Sección #32]], text = [[
01) 38 Arathi Highlands ( log )
02) At Refuge Pointe, entrega "Malin's Request" 47.47.
03) Next hacia Bonfire, acepta "Worth Its Weight in Gold" 46.48.
04) Go NE y click en Shards de Myzrael 62.34 a acepta "The Princess Trapped".
05) ve al este de Hammerfall (Horde town, run sur alrededor de it) y haz "The Princess Trapped": mata y saquea al Kobolds, en y afuera de de la cueva entrance 83.36.  TIP:  Look paral tree y rock 81.40, it shows where el hidden path está a la cueva.  NOTE:  If have mining, luego mine as many Lesser Bloodstone Deposits as can.  These están usad para an Alliance misión only en STV or sell good en AH.
06) Once done, ve al Iridescent Shards (en end de la cueva 84.31) y entrega "The Princess Trapped", acepta "Stones of Binding".
07) Exit la cueva, luego ve al oeste hacia Circle de East Binding (ve al sur de Hammerfall) y haz part de "Stones of Binding": saqueal Stone de East Binding 67.30 paral Cresting Key.
08) ve al sur a Go'Shek Farm y up en ledge, entrega "Hints of a New Plague?" 60.54, aceptal next part.
09) NOTE:  El next part de "Hints of a New Plague?" involves mata y saquea aing el Forsaken Courier /target (lvl 35 con four lvl 35 bodyguards).  This NPC patrols en main path between Go'Shek Farm y Tarren Mill (Horde town en Hillsbrad).  So if run into him go ahead y try a mata y saquea a him para this misión, but just continue en:
10) Go SE a Witherbark Village alrededor de 63.67 y haz "Worth Its Weight in Gold": mata y saquea al trolls alrededor del village.  El tusks can drop desde any de them, el Witherbark Medicine Pouch drops only desde Witherbark Witch Doctors, y el Shadow Hunter Knife drops only desdel Witherbark Shadow Hunters (found only en la cueva entrance 68.76).
 ]], }
SKquests_GuideES.Alliance[100] = {title = [[Guía de Leveo - Sección #33]], text = [[
01) Go NW y haz part de "Stones of Binding": click en Stone de Outer Binding 52.51 paral Thundering Key.
02) ve al oeste a Refuge Pointe y entrega "Worth Its Weight in Gold" 46.48.
03) Next a by el Forge, acepta "Wand over Fist" 47.47.
04) You can get repaired/resupplied desde Jannos Ironwill 46.48 junto a Bonfire.
05) ve al sur a Boulderfist Hall y entra en el southern most cave entrance 54.78 y haz "Wand over Fist": hug el left side de la cueva until get a Kor'gresh Coldrage /target 55.82 y mata y saquea a this ogre.
06) Go back norte a Refuge Pointe y entrega "Wand over Fist" (47.47, #2 en map).
07) N/A
08) N/A
